// ProfileServiceHandler is an implementation of the mavio.acquisition.v1.ProfileService service.
type ProfileServiceHandler interface {
	// ListQualityDefinitions lists the qualities of a kind with their
	// sizes, Radarr's defaults for movies and Sonarr's for series until
	// changed.
	ListQualityDefinitions(context.Context, *v1.ListQualityDefinitionsRequest) (*v1.ListQualityDefinitionsResponse, error)
	// UpdateQualityDefinitions changes the sizes of qualities of a kind.
	UpdateQualityDefinitions(context.Context, *v1.UpdateQualityDefinitionsRequest) (*v1.UpdateQualityDefinitionsResponse, error)
	ListQualityProfiles(context.Context, *v1.ListQualityProfilesRequest) (*v1.ListQualityProfilesResponse, error)
	CreateQualityProfile(context.Context, *v1.CreateQualityProfileRequest) (*v1.CreateQualityProfileResponse, error)
	UpdateQualityProfile(context.Context, *v1.UpdateQualityProfileRequest) (*v1.UpdateQualityProfileResponse, error)
	// DeleteQualityProfile fails with FAILED_PRECONDITION while movies or
	// series use the profile.
	DeleteQualityProfile(context.Context, *v1.DeleteQualityProfileRequest) (*v1.DeleteQualityProfileResponse, error)
	ListCustomFormats(context.Context, *v1.ListCustomFormatsRequest) (*v1.ListCustomFormatsResponse, error)
	CreateCustomFormat(context.Context, *v1.CreateCustomFormatRequest) (*v1.CreateCustomFormatResponse, error)
	UpdateCustomFormat(context.Context, *v1.UpdateCustomFormatRequest) (*v1.UpdateCustomFormatResponse, error)
	// DeleteCustomFormat also removes the format's scores from profiles.
	DeleteCustomFormat(context.Context, *v1.DeleteCustomFormatRequest) (*v1.DeleteCustomFormatResponse, error)
	// ListDelayProfiles lists the delay profiles by order, the default
	// last.
	ListDelayProfiles(context.Context, *v1.ListDelayProfilesRequest) (*v1.ListDelayProfilesResponse, error)
	// CreateDelayProfile adds a profile before the default one.
	CreateDelayProfile(context.Context, *v1.CreateDelayProfileRequest) (*v1.CreateDelayProfileResponse, error)
	UpdateDelayProfile(context.Context, *v1.UpdateDelayProfileRequest) (*v1.UpdateDelayProfileResponse, error)
	// DeleteDelayProfile fails with FAILED_PRECONDITION for the default
	// profile.
	DeleteDelayProfile(context.Context, *v1.DeleteDelayProfileRequest) (*v1.DeleteDelayProfileResponse, error)
	// ReorderDelayProfiles orders the profiles other than the default one.
	ReorderDelayProfiles(context.Context, *v1.ReorderDelayProfilesRequest) (*v1.ReorderDelayProfilesResponse, error)
	ListReleaseProfiles(context.Context, *v1.ListReleaseProfilesRequest) (*v1.ListReleaseProfilesResponse, error)
	CreateReleaseProfile(context.Context, *v1.CreateReleaseProfileRequest) (*v1.CreateReleaseProfileResponse, error)
	UpdateReleaseProfile(context.Context, *v1.UpdateReleaseProfileRequest) (*v1.UpdateReleaseProfileResponse, error)
	DeleteReleaseProfile(context.Context, *v1.DeleteReleaseProfileRequest) (*v1.DeleteReleaseProfileResponse, error)
	ListRemotePathMappings(context.Context, *v1.ListRemotePathMappingsRequest) (*v1.ListRemotePathMappingsResponse, error)
	CreateRemotePathMapping(context.Context, *v1.CreateRemotePathMappingRequest) (*v1.CreateRemotePathMappingResponse, error)
	DeleteRemotePathMapping(context.Context, *v1.DeleteRemotePathMappingRequest) (*v1.DeleteRemotePathMappingResponse, error)
}

